def is_majority(arr, n, element):
    # Subproblem 1: Input Handling
    if not isinstance(arr, list) or not all(isinstance(x, int) for x in arr):
        raise ValueError("Input must be a list of integers.")
    if not isinstance(n, int) or n <= 0 or len(arr) != n:
        raise ValueError("Invalid length of the array.")
    if not arr:
        return False

    # Helper function: Binary search to find the first occurrence of the element
    def find_first_occurrence(arr, n, element):
        low, high = 0, n - 1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] == element:
                if mid == 0 or arr[mid - 1] < element:
                    return mid
                else:
                    high = mid - 1
            elif arr[mid] < element:
                low = mid + 1
            else:
                high = mid - 1
        return -1

    # Subproblem 2: Core Algorithm - Check for Majority Element
    first_occurrence = find_first_occurrence(arr, n, element)
    if first_occurrence == -1:
        return False  # Element not found in the array

    # Check if the element appears more than n/2 times
    majority_index = first_occurrence + n // 2
    if majority_index < n and arr[majority_index] == element:
        return True
    return False
