def max_Product(arr):
    # Step 1: Input Handling
    if not isinstance(arr, list) or len(arr) < 2:
        raise ValueError("Input must be a list with at least two integers.")
    if not all(isinstance(x, int) for x in arr):
        raise ValueError("All elements in the list must be integers.")

    # Step 2: Core Algorithm
    # Initialize variables to track the two largest and two smallest numbers
    max1 = max2 = float('-inf')  # Two largest numbers
    min1 = min2 = float('inf')   # Two smallest numbers

    for num in arr:
        # Update the two largest numbers
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        # Update the two smallest numbers
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Calculate the products of the two largest and two smallest numbers
    product1 = max1 * max2
    product2 = min1 * min2

    # Step 3: Returning the Result
    if product1 >= product2:
        return (min(max1, max2), max(max1, max2))
    else:
        return (min(min1, min2), max(min1, min2))

# Example usage and test
assert max_Product([1, 2, 3, 4, 7, 0, 8, 4]) == (7, 8)
assert max_Product([-10, -20, 1, 3, 2, -5]) == (-20, -10)
assert max_Product([5, 6]) == (5, 6)
assert max_Product([-1, -2, -3, -4]) == (-4, -3)
